/**
 * 文件头写着「这是生成的」：sqlc、protoc、openapi-generator、Flutter 的插件注册文件……
 * 后缀规则（lib/analysis-target.ts）只认得 .pb.go、_gen.go 这类；Chandler 的 internal/store/sqlc/*.sql.go、
 * agentportal 的 internal/dbgen/、clashmi 的 GeneratedPluginRegistrant 都是靠文件头才知道的，
 * 一次分析选中的文件里它们占到一成多。生成的代码不描述产品怎么做决定，读它只是花额度。
 *
 * 只认两种写法，都要求落在注释行上、在文件开头：
 *   - @generated（protoc、OpenAPI 生成器、tsdoc 的惯例）；
 *   - 同一行既说「generated」又说「do not edit / do not modify」。
 * 不认只说了「generated」的：审计（2026-11-27）里 Chandler 的 internal/otp/service.go
 * （验证码用加密随机数生成）、OpenMAIC 的 kling-adapter.ts（JWT 由 Access Key 生成）
 * 和 fonts.config.mjs（别的文件由它生成）都是产品代码。现在很多手写代码的文件头还写着
 * 「Generated with Claude」，更是不能当生成文件。
 */
const HEADER_LINES = 15;

/** 注释行的开头：C 系、shell/Python/Ruby 的 #、块注释里的 *、HTML、SQL、Lisp。 */
const COMMENT = /^\s*(?:\/\/|#|\*|\/\*|<!--|--|%%|;)/;
const TAG = /@(?:auto-?)?generated\b/i;
const GENERATED = /\bgenerated\b/i;
const ADMONITION = /\b(?:do not|don'?t|never)\s+(?:edit|modify|change)\b/i;
const GENERATED_BY = /\bgenerated (?:by|with|from|using) ([\w@-]+(?:[./][\w@-]+)*)/i;

const ARTICLES: ReadonlySet<string> = new Set(["the", "a", "an", "this", "that"]);

/** 文件头有没有生成的标记；有就说出是谁生成的。 */
export function generatedFileMarker(lines: readonly string[]): string | null {
  for (const line of lines.slice(0, HEADER_LINES)) {
    if (!COMMENT.test(line)) continue;
    if (TAG.test(line)) return "@generated";
    if (GENERATED.test(line) && ADMONITION.test(line)) {
      // 「generated by the protocol buffer compiler」：冠词不是工具名。
      const generator = GENERATED_BY.exec(line)?.[1];
      return generator === undefined || ARTICLES.has(generator.toLowerCase()) ? "generated file" : generator;
    }
  }
  return null;
}
